<div class="page-heading"><p class="eyebrow">Outreach</p><h1>Campaigns</h1><p class="muted">Plan, review and send. Every recipient × part consumes one daily message-part.</p></div>
<div class="two-col"><section class="panel"><h2>Recent campaigns</h2><?php if(!$campaigns): ?><div class="empty-card"><h3>No campaigns yet</h3><p>Choose a template and audience below to create your first campaign.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Status</th><th>Recipients</th><th>Parts</th><th>Created</th></tr></thead><tbody><?php foreach($campaigns as $c): ?><tr><td><a href="<?= e(url('campaigns/'.$c['id'])) ?>"><?= e($c['name']) ?></a><br><span class="muted small"><?= e($c['template_name']) ?></span></td><td><span class="badge badge-<?= e($c['status']) ?>"><?= e(ucfirst($c['status'])) ?></span></td><td><?= (int)$c['recipient_count'] ?></td><td><?= (int)$c['part_count'] ?></td><td class="muted small"><?= e(date('M j, Y',strtotime($c['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<aside class="panel"><h2>New campaign</h2><?php if(!$templates): ?><div class="empty-card"><h3>Template required</h3><p>Create a message template before sending a campaign.</p><a class="button button-secondary" href="<?= e(url('templates')) ?>">Create template</a></div><?php else: ?><form method="post" action="<?= e(url('campaigns/create')) ?>" class="stack"><?= csrf_field() ?><label for="campaign-name">Campaign name</label><input id="campaign-name" name="name" required maxlength="160" placeholder="e.g. October product update">
<label for="template-id">Message template</label><select id="template-id" name="template_id" required><?php foreach($templates as $t): ?><option value="<?= (int)$t['id'] ?>"><?= e($t['name']) ?> (<?= count($t['parts']) ?> part<?= count($t['parts'])===1?'':'s' ?>)</option><?php endforeach; ?></select>
<fieldset><legend>Individual contacts</legend><div class="checkbox-list scroll-list"><?php foreach($contacts as $c): ?><label class="check"><input type="checkbox" name="contact_ids[]" value="<?= (int)$c['id'] ?>"> <?= e($c['name']?:$c['phone_e164']) ?><span class="muted small"> <?= e($c['phone_e164']) ?></span></label><?php endforeach; ?></div></fieldset>
<fieldset><legend>Groups</legend><div class="checkbox-list"><?php foreach($groups as $g): ?><label class="check"><input type="checkbox" name="group_ids[]" value="<?= (int)$g['id'] ?>"> <?= e($g['name']) ?> <span class="muted small">(<?= (int)$g['contact_count'] ?>)</span></label><?php endforeach; ?></div></fieldset>
<p class="hint">After reviewing the audience and projected quota, you will enter an unused daily access code assigned to your account to confirm.</p>
<button class="button" type="submit">Review campaign</button></form><?php endif; ?></aside></div>
